```go
package main

import "fmt"

func inner() {
    defer fmt.Println("inner cleanup")
    panic("broken invariant")
}

func outer() {
    defer fmt.Println("outer cleanup")
    inner()
    fmt.Println("unreachable")
}

func main() { outer() }
```
Before the runtime reports the unhandled panic, the program prints `inner cleanup` and then `outer cleanup`. The `unreachable` line never executes.

```go
package main

import (
    "fmt"
    "strconv"
)

func parsePort(text string) (int, error) {
    port, err := strconv.Atoi(text)
    if err != nil { return 0, fmt.Errorf("invalid port %q: %w", text, err) }
    if port < 1 || port > 65535 { return 0, fmt.Errorf("port out of range: %d", port) }
    return port, nil
}

func main() {
    _, err := parsePort("abc")
    fmt.Println(err != nil)
}
```
The output is `true`. Invalid user input remains an expected, inspectable result instead of terminating the program.

```go
package main

import (
    "errors"
    "fmt"
)

var zeroDivisor = errors.New("zero divisor")

func divide(a, b int) int {
    if b == 0 { panic(zeroDivisor) }
    return a / b
}

func safeDivide(a, b int) (value int, err error) {
    defer func() {
        if recovered := recover(); recovered != nil {
            if recovered == zeroDivisor { err = zeroDivisor; return }
            panic(recovered)
        }
    }()
    return divide(a, b), nil
}

func main() { fmt.Println(safeDivide(8, 0)) }
```
The output is `0 zero divisor`. Only the known sentinel is translated; an unexpected panic would continue unwinding.

```go
package main

import "fmt"

func safeRun(result chan<- error, task func()) {
    defer func() {
        if value := recover(); value != nil {
            result <- fmt.Errorf("task panicked: %v", value)
        }
    }()
    task()
    result <- nil
}

func main() {
    result := make(chan error, 1)
    go safeRun(result, func() { panic("boom") })
    fmt.Println(<-result)
}
```
The worker's own defer converts the panic, and the parent prints `task panicked: boom`. A parent-only recover could not intercept it.

