```go
package main

import "fmt"

func handle(value any) { fmt.Println("recovered:", value) }

func safe() {
    defer func() {
        value := recover()
        if value != nil { handle(value) }
    }()
    panic("boom")
}

func main() { safe(); fmt.Println("continued") }
```
The output is `recovered: boom` and `continued`. The special call is direct in the deferred body; ordinary handling happens afterward.
